{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.com/schemas/beta-cruiser.json",
  "title": "beta cruiser",
  "description": "a schema for a beta cruiser",
  "type": "object",
  "properties": {
    "model": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[a-z ]+$",
      "description": "the model of the beta cruiser"
    },
    "engine": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[a-z ]+$",
      "description": "the engine of the beta cruiser"
    },
    "placeholder": {
      "type": "string",
      "minLength": 1,
      "pattern": "^\\[[a-z ]+\\]$",
      "description": "a placeholder represented by square brackets"
    }
  },
  "required": ["model", "engine", "placeholder"],
  "additionalProperties": false
}
